steps.command:
cd /opt/kubespray/release-2.32 && \
/opt/kubespray/venv-release-2.32/bin/ansible-playbook -i /opt/kubespray/inventory/prod-staging/hosts.ini \
  -b --become-user=root cluster.yml -e kube_version={{version.kubernetes}}

docker compose ps
ip -br addr show | grep {{value.edgeVip}}
keepalived --version
